-- Run this file in DBeaver while connected to the `riya_local` database.
create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique, name text not null, email text not null unique, phone text, role text not null default 'CUSTOMER' check(role in ('CUSTOMER','ADMIN')), created_at timestamptz not null default now());
create table if not exists categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, image_url text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null, short_description text not null, category_id uuid not null references categories(id) on delete restrict, weight text, ingredients text, thumbnail_url text, images jsonb not null default '[]', is_featured boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, name text not null, size numeric(10,2) not null check(size > 0), unit text not null check(unit in ('ml','L','g','kg')), sku text not null unique, price numeric(12,2) not null check(price >= 0), sale_price numeric(12,2) check(sale_price >= 0 and sale_price <= price), stock integer not null default 0 check(stock >= 0), is_active boolean not null default true);
create table if not exists store_settings (id uuid primary key default gen_random_uuid(), store_name text not null default 'Riya', currency text not null default 'INR', shipping_fee numeric(12,2) not null default 50, free_shipping_threshold numeric(12,2) not null default 999, support_phone text, support_email text);
create table if not exists contact_settings (id uuid primary key default gen_random_uuid(), business_name text not null default 'Riya', phone text, email text, whatsapp text, address text, google_maps_url text, instagram_url text, facebook_url text, business_hours text);
create table if not exists orders (id uuid primary key default gen_random_uuid(), order_number text not null unique, user_id uuid, customer_name text not null, customer_phone text not null, customer_email text not null, shipping_address text not null, city text not null, district text not null, state text not null, pincode text not null check(pincode ~ '^[0-9]{6}$'), subtotal numeric(12,2) not null, shipping_fee numeric(12,2) not null, total numeric(12,2) not null, payment_method text not null default 'COD', payment_status text not null default 'PENDING', status text not null default 'PENDING' check(status in ('PENDING','CONFIRMED','PROCESSING','PACKED','SHIPPED','DELIVERED','CANCELLED')), created_at timestamptz not null default now());
create table if not exists order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, product_id uuid not null references products(id), variant_id uuid not null references product_variants(id), product_name text not null, variant_name text not null, quantity integer not null check(quantity > 0), unit_price numeric(12,2) not null, total_price numeric(12,2) not null);
create table if not exists order_status_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, status text not null, note text, updated_by uuid, created_at timestamptz not null default now());
create index if not exists products_category_id_idx on products(category_id); create index if not exists variants_product_id_idx on product_variants(product_id); create index if not exists orders_user_id_idx on orders(user_id); create index if not exists orders_status_created_at_idx on orders(status,created_at desc); create index if not exists order_items_order_id_idx on order_items(order_id);
insert into profiles(user_id,name,email,phone,role) values ('11111111-1111-1111-1111-111111111111','Local Admin','admin@riya.local','9876543210','ADMIN'),('22222222-2222-2222-2222-222222222222','Local Customer','customer@riya.local','9876543211','CUSTOMER') on conflict(user_id) do nothing;
insert into categories(name,slug,description) values ('Gingelly Oil','gingelly-oil','Traditional cold pressed sesame oil'),('Groundnut Oil','groundnut-oil','Fresh cold pressed groundnut oil'),('Coconut Oil','coconut-oil','Pure coconut oil') on conflict(slug) do nothing;
insert into products(name,slug,description,short_description,category_id,ingredients,is_featured) select 'Cold Pressed Gingelly Oil','cold-pressed-gingelly-oil','Aromatic sesame oil for everyday cooking.','Pure cold pressed sesame oil.',id,'100% sesame seeds',true from categories where slug='gingelly-oil' on conflict(slug) do nothing;
insert into products(name,slug,description,short_description,category_id,ingredients) select 'Cold Pressed Groundnut Oil','cold-pressed-groundnut-oil','Naturally filtered groundnut oil.','Pure cold pressed groundnut oil.',id,'100% groundnuts' from categories where slug='groundnut-oil' on conflict(slug) do nothing;
insert into product_variants(product_id,name,size,unit,sku,price,sale_price,stock) select p.id,v.name,v.size,v.unit,v.sku,v.price,v.sale,v.stock from products p cross join (values ('500ml',500::numeric,'ml','LOCAL-GING-500',210::numeric,199::numeric,40),('1L',1::numeric,'L','LOCAL-GING-1L',390::numeric,375::numeric,50)) v(name,size,unit,sku,price,sale,stock) where p.slug='cold-pressed-gingelly-oil' on conflict(sku) do nothing;
insert into product_variants(product_id,name,size,unit,sku,price,stock) select p.id,v.name,v.size,v.unit,v.sku,v.price,v.stock from products p cross join (values ('500ml',500::numeric,'ml','LOCAL-GROUND-500',190::numeric,45),('1L',1::numeric,'L','LOCAL-GROUND-1L',360::numeric,50)) v(name,size,unit,sku,price,stock) where p.slug='cold-pressed-groundnut-oil' on conflict(sku) do nothing;
insert into store_settings(store_name,currency,shipping_fee,free_shipping_threshold,support_phone,support_email) select 'Riya Local Demo','INR',50,999,'9876543210','support@riya.local' where not exists(select 1 from store_settings);
insert into contact_settings(business_name,phone,email,address,business_hours) select 'Riya Local Demo','9876543210','hello@riya.local','Coimbatore, Tamil Nadu','Mon-Sat, 9 AM - 6 PM' where not exists(select 1 from contact_settings);
